steps.body:
A for loop does not have to move one index at a time. Change the start or the update to visit only some positions:

```cpp harness
#include <bits/stdc++.h>

int main() {
    const std::vector<int> v = {10, 15, 21, 4, 7, 12};
    const std::size_t k = 3;
    {{code}}
    return 0;
}
```

```cpp
for (std::size_t i = 0; i < v.size(); i += 2) { // indexes 0, 2, 4, ...
    std::cout << ' ' << v[i];
}
std::cout << '\n';
for (std::size_t i = 1; i < v.size(); i += 2) { // indexes 1, 3, 5, ...
    std::cout << ' ' << v[i];
}
std::cout << '\n';
for (std::size_t i = 0; i < v.size(); i += k) { // every k-th element
    std::cout << ' ' << v[i];
}
std::cout << '\n';
```

The condition `i < v.size()` still guards every jump, so stepping past the end just stops the loop.

To skip by *value* instead of by position, test the element and `continue` to the next one:

```cpp harness
#include <bits/stdc++.h>

int main() {
    const std::vector<int> v = {10, 15, 21, 4, 7, 12};
    {{code}}
    std::cout << '\n';
    return 0;
}
```

```cpp
for (int x : v) {
    if (x % 2 == 0) {
        continue; // even, skip it
    }
    std::cout << ' ' << x;
}
```

Test for odd with `x % 2 != 0`, not `x % 2 == 1`. The sign of `%` follows the left operand, so `-3 % 2` is `-1` and the second test would miss negative odd numbers.

When the first index printed is not 0, `if (i > 0)` no longer places separators correctly. Print the label first, then a space *before* each value.

example.code:
#include <cstddef>
#include <iostream>
#include <vector>

int main() {
    const std::vector<int> nums = {10, 15, 21, 4, 7, 12};

    std::cout << "Even indexes:";
    for (std::size_t i = 0; i < nums.size(); i += 2) {
        std::cout << ' ' << nums[i];
    }
    std::cout << '\n';

    std::cout << "Odd indexes:";
    for (std::size_t i = 1; i < nums.size(); i += 2) {
        std::cout << ' ' << nums[i];
    }
    std::cout << '\n';

    std::cout << "Odd values:";
    for (int x : nums) {
        if (x % 2 == 0) {
            continue;
        }
        std::cout << ' ' << x;
    }
    std::cout << '\n';
    return 0;
}

