#include <cstddef>
#include <iostream>
#include <vector>

int main() {
    const std::vector<int> rain = {4, 7, 1, 6, 6, 9};

    int biggestRise = 0;
    for (std::size_t i = 1; i < rain.size(); ++i) {
        const int rise = rain[i] - rain[i - 1];
        if (rise > biggestRise) {
            biggestRise = rise;
        }
    }
    std::cout << "Biggest rise: " << biggestRise << '\n';

    std::vector<int> totals;
    int running = 0;
    for (int r : rain) {
        running += r;
        totals.push_back(running);
    }
    std::cout << "Running totals:";
    for (int t : totals) {
        std::cout << ' ' << t;
    }
    std::cout << '\n';

    const std::size_t WINDOW_SIZE = 3;
    int windowSum = 0;
    for (std::size_t i = 0; i < WINDOW_SIZE; ++i) {
        windowSum += rain[i];
    }
    int best = windowSum;
    for (std::size_t i = WINDOW_SIZE; i < rain.size(); ++i) {
        windowSum += rain[i] - rain[i - WINDOW_SIZE];
        if (windowSum > best) {
            best = windowSum;
        }
    }
    std::cout << "Best 3-day sum: " << best << '\n';
    return 0;
}
